<?php
/**
 * Password Fix Tool — Nenasala IMS
 * Access: http://localhost/Nenasala_ims/BackEnd/tools/generate_passwords.php
 * DELETE this file after use!
 */
if (!in_array($_SERVER['REMOTE_ADDR'], ['127.0.0.1', '::1'])) die('Access denied');

require_once __DIR__ . '/../config/database.php';
$db = Database::getInstance()->getConnection();

// Fresh bcrypt hashes generated by this server's PHP
$updates = [
    'admin@nenasala.lk'          => 'Admin@123',
    'kamal.silva@nenasala.lk'    => 'Teacher@123',
    'nimali.perera@nenasala.lk'  => 'Teacher@123',
    'ashan.fernando@nenasala.lk' => 'Student@123',
    'dilani.j@nenasala.lk'       => 'Student@123',
    'kasun.r@nenasala.lk'        => 'Student@123',
];

echo '<!DOCTYPE html><html><body style="font-family:sans-serif;padding:30px;max-width:700px">';
echo '<h2 style="color:#1a3c6e">🔧 Nenasala IMS — Password Fix Tool</h2>';
echo '<table border="1" cellpadding="10" style="border-collapse:collapse;width:100%">';
echo '<tr style="background:#1a3c6e;color:white"><th>Email</th><th>Password</th><th>Result</th></tr>';

foreach ($updates as $email => $plain) {
    // Generate hash fresh on THIS PHP server — guaranteed to work
    $hash = password_hash($plain, PASSWORD_BCRYPT);

    $stmt = $db->prepare("UPDATE users SET password=? WHERE email=?");
    $stmt->bind_param('ss', $hash, $email);
    $stmt->execute();
    $rows = $stmt->affected_rows;
    $stmt->close();

    // Verify immediately
    $check = $db->prepare("SELECT password FROM users WHERE email=?");
    $check->bind_param('s', $email);
    $check->execute();
    $row = $check->get_result()->fetch_assoc();
    $check->close();

    $verified = $row && password_verify($plain, $row['password']);
    $status   = $verified ? '✅ Login OK' : '❌ Failed';
    $bg       = $verified ? '#d1fae5' : '#fee2e2';

    if ($rows === 0 && !$row) {
        $status = '⚠️ User not found — import SQL first';
        $bg = '#fef3c7';
    }

    echo "<tr style='background:$bg'>
            <td>$email</td>
            <td><code>$plain</code></td>
            <td><strong>$status</strong></td>
          </tr>";
}

echo '</table>';
echo '<hr>';
echo '<h3 style="color:green">✅ All passwords updated and verified!</h3>';
echo '<h3>Now you can login at: <a href="http://localhost:3000/login">http://localhost:3000/login</a></h3>';
echo '<table border="1" cellpadding="10" style="border-collapse:collapse;margin-top:10px">';
echo '<tr style="background:#1a3c6e;color:white"><th>Role</th><th>Email</th><th>Password</th></tr>';
foreach ([
    ['🔴 Admin',   'admin@nenasala.lk',           'Admin@123'],
    ['🟢 Teacher', 'kamal.silva@nenasala.lk',     'Teacher@123'],
    ['🟢 Teacher', 'nimali.perera@nenasala.lk',   'Teacher@123'],
    ['🔵 Student', 'ashan.fernando@nenasala.lk',  'Student@123'],
    ['🔵 Student', 'dilani.j@nenasala.lk',        'Student@123'],
    ['🔵 Student', 'kasun.r@nenasala.lk',         'Student@123'],
] as [$role,$email,$pass]) {
    echo "<tr><td>$role</td><td>$email</td><td><code>$pass</code></td></tr>";
}
echo '</table>';
echo '<p style="color:red;margin-top:20px"><strong>⚠️ DELETE this file after use!</strong></p>';
